ail":"consulting@sbcgroup.in","telephone":"+91-8128310116","address":{"@type":"PostalAddress","addressLocality":"Ahmedabad","addressRegion":"Gujarat","addressCountry":"IN"},"areaServed":[{"@type":"City","name":"Ahmedabad"},{"@type":"State","name":"Gujarat"},{"@type":"Country","name":"India"}],"founder":{"@type":"Person","name":"Sagar Burse","honorificSuffix":"PhD","jobTitle":"Founder & Principal Consultant","url":"https://sbcgroup.in/founder","image":"https://sbcgroup.in/images/founder/sagar-burse-author.webp","sameAs":["https://www.linkedin.com/in/drsagarburse/"]},"knowsAbout":["Institution building","Skill development","Feasibility studies","Market research","Business operations consulting","MSME consulting","Business process improvement","Business process management","SOP design","GAP360 gap analysis"],"sameAs":["https://www.linkedin.com/company/sbcglobal/","https://www.facebook.com/sbcgroup.in","https://www.instagram.com/sbcgroup.in"]}</script><script type="application/ld+json">{"@context":"https://schema.org","@type":"Service","serviceType":"Market research and feasibility studies","name":"Market Research & Feasibility Studies","provider":{"@id":"https://sbcgroup.in/#professional-service"},"areaServed":[{"@type":"City","name":"Ahmedabad"},{"@type":"State","name":"Gujarat"}],"description":"Market research, feasibility studies and DPRs for businesses, institutions and consulting firms in Ahmedabad and Gujarat."}</script><script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is the difference between a feasibility study and a DPR?","acceptedAnswer":{"@type":"Answer","text":"A feasibility study answers whether to proceed: demand, competition, location and financial viability. A DPR is the detailed plan that follows: design, infrastructure, staffing, costs and timeline, often needed by a regulator, bank or funding body. We do both, and a feasibility study often becomes the first part of the DPR."}},{"@type":"Question","name":"How long does a feasibility study or market research project take?","acceptedAnswer":{"@type":"Answer","text":"It depends on the scope and on whether primary fieldwork is needed. After the fixed-fee diagnostic you receive a written timeline for your study, so the schedule is agreed before the full project starts."}},{"@type":"Question","name":"Will you tell us if the idea should not go ahead?","acceptedAnswer":{"@type":"Answer","text":"Yes. Each study ends with a clear go / no-go recommendation and the risks behind it, including when the answer is not what the promoter hoped for."}},{"@type":"Question","name":"Do you work with consulting firms and research agencies?","acceptedAnswer":{"@type":"Answer","text":"Yes. We act as a research partner under your engagement, to your standards and timelines. Your client relationship stays with you."}},{"@type":"Question","name":"What do you need from us to begin?","acceptedAnswer":{"@type":"Answer","text":"The decision you are trying to make, the location or segment, your budget range, any data you already hold and your deadline. A short call with Dr. Sagar is enough to start."}}]}</script><header class="sticky top-0 z-50 border-b border-ink-tint bg-paper/95 backdrop-blur"><div class="shell flex h-20 items-center justify-between gap-6 lg:h-28"><a href="/" class="flex min-w-0 shrink-0 items-center"><img src="/sbc-logo.png" alt="Sagar Burse Consulting SBC logo" width="96" height="96" class="size-14 shrink-0 rounded-full sm:size-16 lg:size-24"/></a><nav aria-label="Main" class="hidden items-center gap-2 lg:flex"><div class="relative"><button type="button" aria-expanded="false" class="flex items-center gap-1 rounded px-3 py-2 text-[16px] font-bold text-ink transition-colors hover:text-gold">About Us<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide luc